const crypto = require('crypto');

const inquiry_id = 'inq_' + crypto.randomUUID();
const date = new Date();
const yyyy = date.getFullYear();
const mm = String(date.getMonth() + 1).padStart(2, '0');
const dd = String(date.getDate()).padStart(2, '0');
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const tracking_number = 'TRK-' + yyyy + mm + dd + '-' + randomSuffix;

const raw = $input.first().json;
const item = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

const fromEmail = item.from?.value?.[0]?.address || item.customer_email || item.from || item.email || 'customer@example.com';
const fromName = item.from?.value?.[0]?.name || item.customer_name || item.senderName || item.name || 'Valued Customer';
const subject = item.subject || 'Inquiry';
const bodyText = item.textPlain || item.snippet || (typeof item.body === 'string' ? item.body : '') || item.text || item.message || '';
const threadId = item.threadId || item.id || item.thread_id || ('th_' + randomSuffix);

return [{
  json: {
    inquiry_id,
    tracking_number,
    customer_email: fromEmail,
    customer_name: fromName,
    subject,
    body: bodyText,
    thread_id: threadId,
    timestamp: date.toISOString()
  }
}];

const item = $('Idempotency & Format Input').item.json;
const text = (item.subject + ' ' + item.body).toLowerCase();

let primary_intent = 'Sales';
let secondary_intent = 'quote_inquiry';
let is_sensitive = false;
let sensitivity_reason = null;
let customer_sentiment = 'neutral';

const sensitiveKeywords = [
  'refund', 'refund request', 'chargeback', 'dispute', 'payment dispute', 
  'serious payment dispute', 'attorney', 'lawyer', 'lawsuit', 'legal action', 
  'legal threat', 'sue', 'court', 'bbb', 'better business bureau', 
  'consumer protection', 'regulatory complaint', 'attorney general', 
  'damage', 'damaged my car', 'fraud', 'scam', 'stolen', 'threat', 'negligence'
];

for (const kw of sensitiveKeywords) {
  if (text.includes(kw)) {
    is_sensitive = true;
    sensitivity_reason = 'Matched safety trigger: ' + kw;
    primary_intent = 'Complaint';
    customer_sentiment = 'frustrated';
    break;
  }
}

if (!is_sensitive) {
  if (text.includes('pay') || text.includes('invoice') || text.includes('receipt') || text.includes('bill')) {
    primary_intent = 'Payment';
  } else if (text.includes('book') || text.includes('schedule') || text.includes('appointment') || text.includes('drop off')) {
    primary_intent = 'Booking';
  } else if (text.includes('complaint') || text.includes('broken') || text.includes('unhappy') || text.includes('delay')) {
    primary_intent = 'Complaint';
  } else {
    primary_intent = 'Sales';
  }
}

let year = null;
const yearMatch = text.match(/\b(19\d{2}|20\d{2})\b/);
if (yearMatch) year = parseInt(yearMatch[1], 10);

let make = null;
const makes = ['toyota', 'honda', 'ford', 'chevrolet', 'chevy', 'bmw', 'mercedes', 'porsche', 'ferrari', 'jeep', 'ram', 'nissan', 'hyundai'];
for (const m of makes) {
  if (text.includes(m)) {
    make = m.charAt(0).toUpperCase() + m.slice(1);
    break;
  }
}

let model = null;
const models = ['camry', 'civic', 'corolla', 'accord', '330i', 'f-150', 'f150', 'silverado', 'rav4', 'explorer', 'cr-v', '911', 'mustang', 'ram 1500', 'tahoe'];
for (const mo of models) {
  if (text.includes(mo)) {
    model = mo.toUpperCase();
    break;
  }
}

const services = [];
if (text.includes('oil') || text.includes('lube')) services.push('Synthetic Oil Change');
if (text.includes('brake') || text.includes('pad')) services.push('Front Brake Pad Replacement');
if (text.includes('rotor')) services.push('Front Brake Pads & Rotors');
if (text.includes('tire') || text.includes('rotation')) services.push('Tire Rotation');
if (text.includes('coolant') || text.includes('radiator')) services.push('Coolant Flush');
if (text.includes('transmission')) services.push('Transmission Flush');
if (text.includes('diagnostic') || text.includes('check engine')) services.push('Standard Diagnostic');

const ai_summary = 'Customer ' + item.customer_name + ' inquiry for ' + (year ? year + ' ' : '') + (make ? make + ' ' : '') + (model ? model : 'vehicle') + '. Services: ' + (services.length ? services.join(', ') : 'Not specified');

const ticketObj = $('HubSpot: Create Support Ticket (First Invariant)').item.json;
const hubspot_ticket_id = String(ticketObj.objectId || ticketObj.id || ticketObj.properties?.hs_ticket_id?.value || ticketObj.properties?.hs_object_id?.value || '');

return [{
  json: {
    ...item,
    hubspot_ticket_id,
    ai: {
      primary_intent,
      secondary_intent,
      customer_phone: null,
      vehicle: { year, make, model, vin: null },
      services_requested: services,
      is_sensitive,
      sensitivity_reason,
      customer_sentiment,
      ai_summary
    }
  }
}];

const item = $input.first().json;
const ai = item.ai || {};
const vehicle = ai.vehicle || {};

const VEHICLE_TIER_CATALOG = {
  'CAMRY': 'tier_1_sedan_coupe',
  'CIVIC': 'tier_1_sedan_coupe',
  'COROLLA': 'tier_1_sedan_coupe',
  'ACCORD': 'tier_1_sedan_coupe',
  '330I': 'tier_1_sedan_coupe',
  'MUSTANG': 'tier_1_sedan_coupe',
  'RAV4': 'tier_2_suv_crossover',
  'CR-V': 'tier_2_suv_crossover',
  'EXPLORER': 'tier_2_suv_crossover',
  'TAHOE': 'tier_2_suv_crossover',
  'F-150': 'tier_3_truck_van_diesel',
  'F150': 'tier_3_truck_van_diesel',
  'SILVERADO': 'tier_3_truck_van_diesel',
  'RAM 1500': 'tier_3_truck_van_diesel',
  '911': 'tier_4_exotic_commercial'
};

const rawModel = (vehicle.model || '').toUpperCase().trim();
let vehicle_model_found = false;
let vehicle_tier = 'unknown_manual';

if (rawModel && VEHICLE_TIER_CATALOG[rawModel]) {
  vehicle_model_found = true;
  vehicle_tier = VEHICLE_TIER_CATALOG[rawModel];
}

const hasVehicleSpecs = Boolean(vehicle.year && vehicle.make && vehicle.model);
const hasServices = Array.isArray(ai.services_requested) && ai.services_requested.length > 0;
const missing_info = (!hasVehicleSpecs || !hasServices);

return [{
  json: {
    ...item,
    vehicle_model_found,
    vehicle_tier,
    missing_info,
    is_sensitive: Boolean(ai.is_sensitive),
    sensitivity_reason: ai.sensitivity_reason || null
  }
}];

const PRICING_MATRIX = {
  'oil_change_synthetic': { rates: { 'tier_1_sedan_coupe': 79.95, 'tier_2_suv_crossover': 94.95, 'tier_3_truck_van_diesel': 119.95 } },
  'oil_change_diesel': { rates: { 'tier_3_truck_van_diesel': 189.95 } },
  'brake_pads_front': { rates: { 'tier_1_sedan_coupe': 189.00, 'tier_2_suv_crossover': 219.00, 'tier_3_truck_van_diesel': 269.00 } },
  'brake_pads_rotors_front': { rates: { 'tier_1_sedan_coupe': 349.00, 'tier_2_suv_crossover': 419.00, 'tier_3_truck_van_diesel': 499.00 } },
  'tire_rotation': { rates: { 'tier_1_sedan_coupe': 29.95, 'tier_2_suv_crossover': 29.95, 'tier_3_truck_van_diesel': 39.95 } },
  'coolant_flush': { rates: { 'tier_1_sedan_coupe': 149.95, 'tier_2_suv_crossover': 169.95, 'tier_3_truck_van_diesel': 199.95 } },
  'transmission_flush': { rates: { 'tier_1_sedan_coupe': 229.00, 'tier_2_suv_crossover': 259.00, 'tier_3_truck_van_diesel': 299.00 } },
  'diagnostic_fee': { rates: { 'tier_1_sedan_coupe': 149.00, 'tier_2_suv_crossover': 149.00, 'tier_3_truck_van_diesel': 149.00 } }
};

const item = $input.first().json;
const tier = item.vehicle_tier || 'unknown_manual';

if (!item.vehicle_model_found || tier === 'unknown_manual' || tier === 'tier_4_exotic_commercial') {
  return [{
    json: {
      ...item,
      pricing_status: 'manual_quote_required',
      estimated_cost: null,
      quote_note: 'Vehicle model requires custom parts estimation.'
    }
  }];
}

let total = 0;
let requiresManual = false;

for (const s of (item.ai.services_requested || [])) {
  const clean = s.toLowerCase();
  let key = null;
  if (clean.includes('rotors') || clean.includes('pads and rotors')) key = 'brake_pads_rotors_front';
  else if (clean.includes('brake') || clean.includes('pad')) key = 'brake_pads_front';
  else if (clean.includes('diesel oil')) key = 'oil_change_diesel';
  else if (clean.includes('oil')) key = 'oil_change_synthetic';
  else if (clean.includes('tire') || clean.includes('rotation')) key = 'tire_rotation';
  else if (clean.includes('coolant')) key = 'coolant_flush';
  else if (clean.includes('transmission')) key = 'transmission_flush';
  else if (clean.includes('diagnostic')) key = 'diagnostic_fee';

  if (key && PRICING_MATRIX[key]?.rates?.[tier]) {
    total += PRICING_MATRIX[key].rates[tier];
  } else {
    requiresManual = true;
  }
}

return [{
  json: {
    ...item,
    pricing_status: requiresManual ? 'manual_quote_required' : 'quoted_automatically',
    estimated_cost: requiresManual ? null : parseFloat(total.toFixed(2)),
    quote_note: requiresManual ? 'Custom service quote needed.' : 'Deterministic price matched.'
  }
}];
